# Ιατρική ΕΚΠΑ: Οδηγός Σπουδών 2025-26 — 6.1 υποχρεωτικά (transcribed from the table), 7.1 κατ' επιλογήν υποχρεωτικά (parsed).
import re
from lib import save, norm
SRC = "https://school.med.uoa.gr/fileadmin/depts/med.uoa.gr/school/uploads/Odigos_Spoydon/Odigos_Spoydon_2025-2026.pdf"
CORE = {1: ["Βιολογία Ι", "Επιστημολογία, Ιστορία & Ηθική της Ιατρικής", "Ιατρική Χημεία", "Ιατρική Φυσική", "Ιατρική Στατιστική"],
        2: ["Βιολογία ΙΙ - Γενετική", "Νευροανατομία και Νευροφυσιολογία", "Βιολογική Χημεία Ι", "Ιστολογία-Εμβρυολογία Ι"],
        3: ["Περιγραφική Ανατομική ΙΙ", "Φυσιολογία (3ο εξάμηνο)", "Βιολογική Χημεία ΙΙ", "Ιστολογία-Εμβρυολογία ΙΙ"],
        4: ["Περιγραφική Ανατομική Ι", "Φυσιολογία (4ο εξάμηνο)", "Παθολογική Ανατομική Ι", "Γενική Μικροβιολογία - Ανοσολογία", "Παθογενετικοί Μηχανισμοί"],
        5: ["Παθολογική Ανατομική ΙΙ", "Παθολογική Φυσιολογία", "Φαρμακολογία Ι", "Ιατρική Μικροβιολογία", "Ιατρική Ψυχολογία"],
        6: ["Σημειολογία - Νοσολογία", "Χειρουργική Παθολογία Ι", "Κλινική Φαρμακολογία", "Ακτινολογία Ι", "Προληπτική Ιατρική - Δημόσια Υγεία"],
        7: ["Παθολογία", "Χειρουργική Παθολογία ΙΙ", "Γενική Επιδημιολογία και Μεθοδολογία Έρευνας", "Ακτινολογία ΙΙ"]}
ROT89 = ["Πνευμονολογία", "Εντατική Θεραπεία", "Καρδιολογία", "Νευρολογία", "Ουρολογία", "Οφθαλμολογία", "ΩΡΛ", "Ορθοπαιδική Τραυματιολογία",
         "Αναισθησιολογία", "Επείγουσα Ιατρική", "Δερματολογία", "Θεραπευτική"]
ROT1012 = ["Παθολογία", "Παιδιατρική", "Χειρουργική", "Μαιευτική - Γυναικολογία", "Ψυχιατρική", "Ιατροδικαστική - Τοξικολογία"]
rows = [{"name": n, "semester": s, "kind": "core"} for s, ns in CORE.items() for n in ns]
rows += [{"name": n, "semester": 8, "kind": "core", "group": "Κλινική άσκηση 8ου–9ου εξαμήνου (κυκλικά σε ομάδες)"} for n in ROT89]
rows += [{"name": n, "semester": 10, "kind": "core", "group": "Κλινική άσκηση 10ου–12ου εξαμήνου (κυκλικά σε ομάδες)"} for n in ROT1012]
rows.append({"name": "Κατ' επιλογήν τρίμηνο κλινικής άσκησης", "semester": 12, "kind": "elective", "group": "Μία ειδικότητα (π.χ. Καρδιολογία, Νευροχειρουργική, Γενική Ιατρική)"})
L = [norm(l) for l in open("raw/med2.txt")]
a = next(i for i, l in enumerate(L) if l.startswith("7.1 ΚΑΤ’ ΕΠΙΛΟΓΗΝ")); b = next(i for i, l in enumerate(L) if l.startswith("7.2 ΩΡΟΛ"))
group, cur, english = None, None, False
for l in L[a:b]:
    if m := re.match(r"^(?:Α΄ ΤΟΜ ΕΑΣ|[Α-Ω]{1,2}~(.+))", l): group = "Τομέας Βασικών Ιατρικών Επιστημών" if not m[1] else (m[1].title() if "ΤΟΜΕΑΣ" in m[1] else "Διατομεακά"); cur = None; continue
    if m := re.match(r"^\d+ (\d{6}) (.+)$", l):
        cur = {"code": m[1], "name": m[2], "semester": None, "kind": "elective", "group": group}; rows.append(cur); english = m[2] == "ΑΓΓΛΟΦΩΝΟ"; continue
    if not cur or re.match(r"^(Α/Α|A/A|Σε συνεργασία|τον |\(συνεργασία|=== |\d+$|\.\.|[α-ωA-Za-z]{1,2}$)", l) or re.fullmatch(r"((.)\2)+", l.replace(" ", "")): cur = None if (cur and l.startswith(("Σε συνεργασία", "==="))) else cur; continue
    if english: cur["name"] = l; english = False; cur = None if not l.endswith("-") else cur; continue
    if cur["name"].endswith("-"): cur["name"] = cur["name"][:-1] + l
    elif l.startswith("("): cur = None
for r in rows: r["name"] = norm(r["name"].replace("BιοϊατρικήΤεχνολογία", "Βιοϊατρική Τεχνολογία").replace("ΤεχνητήΝοημοσύνη", "Τεχνητή Νοημοσύνη").replace("Xειρ", "Χειρ").replace("Eπιστήμη", "Επιστήμη"))
for r in rows:
    if r.get("group"): r["group"] = r["group"].replace("Τομεας", "Τομέας").replace("Κλινικοεργαστηριακος", "Κλινικοεργαστηριακός").replace("Παθολογιας", "Παθολογίας").replace("Χειρουργικης", "Χειρουργικής").replace("Υγειας Μητερας-Παιδιου", "Υγείας Μητέρας-Παιδιού").replace("Κοινωνικης Ιατρικης -Ψυχιατρικης Και Νευρολογιας", "Κοινωνικής Ιατρικής, Ψυχιατρικής και Νευρολογίας")
save("uoa", "uoa-med", SRC, rows, note="Κατ' επιλογήν υποχρεωτικά: ένα ανά εξάμηνο (2 μονάδες), προσφέρονται σε πολλά εξάμηνα → semester null, group = Τομέας.")
